@import "@fontsource-variable/geist";
@import "@fontsource-variable/inter";

/* Light (faithful): white page, pale-blue panels #f1f5f8, navy #3d5e86 for copy on them, warm
   grey #524f4b for body text, pale sky blue #d3e7ff as the one accent (CTA, icon squares, dots).
   Blocks that sit on the original's dark bands add the `dark` class to themselves, which gives
   the instrument dark below: #1b1b1b page, #524f4b cards, pure black callouts and footer.
   glow is the sky blue #628ad1 (hero sky, chart bars); chart-5 is the peach end of the hero gradient. */
:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.145 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.145 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.145 0 0);
  --primary: oklch(0.921 0.039 253);
  --primary-foreground: oklch(0.145 0 0);
  --secondary: oklch(0.968 0.006 239.8);
  --secondary-foreground: oklch(0.475 0.076 253.9);
  --muted: oklch(0.968 0.006 239.8);
  --muted-foreground: oklch(0.429 0.008 75.3);
  --accent: oklch(0.921 0.039 253);
  --accent-foreground: oklch(0.145 0 0);
  --destructive: oklch(0.577 0.245 27.325);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(0.849 0.006 84.6);
  --input: oklch(0.849 0.006 84.6);
  --ring: oklch(0.635 0.116 261.3);
  --highlight: oklch(0.475 0.076 253.9);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.635 0.116 261.3);
  --chart-1: oklch(0.635 0.116 261.3);
  --chart-2: oklch(0.921 0.039 253);
  --chart-3: oklch(0.475 0.076 253.9);
  --chart-4: oklch(0.773 0.004 91.5);
  --chart-5: oklch(0.963 0.025 65.6);
  --sidebar: oklch(0.968 0.006 239.8);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.635 0.116 261.3);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.921 0.039 253);
  --sidebar-accent-foreground: oklch(0.145 0 0);
  --sidebar-border: oklch(0.849 0.006 84.6);
  --sidebar-ring: oklch(0.635 0.116 261.3);

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --typeface-display: "Geist Variable", "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.25rem;
  --page-width: 86rem;
  --page-gutter: 1rem;
  --section-y: 8rem;
}

.dark {
  --background: oklch(0.222 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.429 0.008 75.3);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0 0 0);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.921 0.039 253);
  --primary-foreground: oklch(0.145 0 0);
  --secondary: oklch(0.269 0 0);
  --secondary-foreground: oklch(0.773 0.004 91.5);
  --muted: oklch(0.269 0 0);
  --muted-foreground: oklch(0.773 0.004 91.5);
  --accent: oklch(0.921 0.039 253);
  --accent-foreground: oklch(0.145 0 0);
  --destructive: oklch(0.704 0.191 22.216);
  --destructive-foreground: oklch(0.985 0 0);
  --border: oklch(1 0 0 / 20%);
  --input: oklch(1 0 0 / 20%);
  --ring: oklch(0.635 0.116 261.3);
  --highlight: oklch(0.815 0.066 259.1);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.635 0.116 261.3);
  --chart-1: oklch(0.635 0.116 261.3);
  --chart-2: oklch(0.921 0.039 253);
  --chart-3: oklch(0.815 0.066 259.1);
  --chart-4: oklch(0.773 0.004 91.5);
  --chart-5: oklch(0.963 0.025 65.6);
  --sidebar: oklch(0.269 0 0);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.635 0.116 261.3);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.429 0.008 75.3);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 20%);
  --sidebar-ring: oklch(0.635 0.116 261.3);
}
